"""Compiled checks for AELLO-C8-S3. GENERATED by solution/recompute.py. DO NOT HAND-EDIT.

The graded deliverable here is a callable data-selection recipe, not a model and not a prediction
array: the verifier CALLS build(pool_index, out_dir) and the frozen trainer then consumes whatever
shard that call emitted. So the delivered bytes these checks read are the recipe source, the shard
manifest build() wrote, the served pool index that carries capture timestamp, site id and burst id,
the verifier-held capture-timestamp table, and the op trace the harness recorded while build() ran.

Nothing below imports the recipe. A verifier that imports agent code to discover its interface has
already executed the recipe inside the grading environment, so the callable contract is read off
the parsed source instead.

Every check runs against those bytes and references no unmeasured quantity, except
balanced_accuracy_over_twelve_classes_ramp, which raises ConstantUnmeasured while tests/constants.json carries nulls.
"""
import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))
SUBMISSION = '/submission/recipe.py'
CHECKS = []

# --- the recipe's callable contract -------------------------------------------------------
BUILD_PARAMS = ('pool_index', 'out_dir')
FROZEN_PACKAGE = 'frozen_trainer'

# --- what ships to the agent --------------------------------------------------------------
POOL_INDEX = 'environment/data/pool_index.csv'
POOL_FIELDS = ('image_id', 'capture_timestamp', 'site_id', 'burst_id', 'label')
DATASET_CARD = 'environment/pool/DATASET_CARD.md'
CLASSES = ('empty', 'wildebeest', 'zebra', 'gazelleThomsons', 'buffalo', 'elephant', 'impala', 'hartebeest', 'giraffe', 'hyenaSpotted', 'warthog', 'guineaFowl')
CLASS_COUNT = 12

# --- what build() must leave behind -------------------------------------------------------
MANIFEST_NAME = 'shard_manifest.json'
MANIFEST_FIELDS = ('source_id', 'label', 'path')
DECLARED_OPS_KEY = 'declared_op_sequence'
RUN_RECORD = '../run_record.json'

# --- what the verifier holds and the agent never sees -------------------------------------
CAPTURE_TIMES = 'pool_capture_times.csv'
BOUNDARY = 'capture_boundary.json'
LABELS_A = 'private_A_labels.npy'
PREDICTIONS_A = 'private_A_predictions.npy'
GUARDED = ('tests/', 'tests/heldout/', 'environment/trainer/')

# --- the selection ops, and the four precedences that are load-bearing --------------------
OP_DEDUP = 'burst_dedup'
OP_DECODE = 'decode'
OP_REBALANCE = 'class_rebalance'
OP_STATISTICS = 'normalization_statistics'
AUGMENTATION_OPS = ('geometry_augment', 'photometric_augment')
ILLUMINATION_REGIMES = ('daylight', 'night_infrared')

# --- the declared bounds. None of these is a ramp constant; the ramp constants are null. ---
ENVELOPE_SECONDS = 3300
SAMPLE_CAP_ROWS = 400000
SIBLING_GAP_BOUND = 0.04
TRAINER_STEPS = 6000
LOG_ACCURACY_TOLERANCE = 0.05
LOG_ELAPSED_TOLERANCE = 0.1
SITE_COVERAGE_FLOOR = 0.5
MAX_SINGLE_SITE_SHARE = 0.2
LITERAL_PRIOR_MAX = 64


class ConstantUnmeasured(Exception):
    """Raised when a check needs a ramp constant that Phase 0 deliberately left null."""


def check(id, weight, knockout, kind):
    def deco(fn):
        CHECKS.append({"id": id, "weight": weight, "knockout": knockout, "kind": kind, "fn": fn})
        return fn
    return deco


def constants():
    with open(os.path.join(HERE, "constants.json")) as fh:
        return json.load(fh)


def require_measured(*names):
    c = constants()
    missing = [n for n in names if c.get(n) is None]
    if missing:
        raise ConstantUnmeasured(
            "AELLO-C8-S3: " + ", ".join(missing) + " are null. Phase 0 authors no measurement; "
            "the Phase 2 measurement wave writes these and this check becomes gradeable then.")
    return c


def evidence(**kw):
    return {"evaluation_target": kw.pop("target", "submitted_artifact"), "values": kw}


@check(id="at_most_one_frame_per_burst_id", weight=4, knockout=False, kind="selection")
def test_at_most_one_frame_per_burst_id():
    ids = manifest_source_ids()
    if not ids:
        return False, evidence(target="emitted_shard", reason="shard_unreadable")
    bursts = burst_of()
    if not bursts:
        return False, evidence(target="emitted_shard", reason="pool_index_unavailable",
                               path=bundle(POOL_INDEX))
    first, collisions, unresolved = {}, [], []
    for source_id in ids:
        burst = bursts.get(source_id)
        if burst is None:
            unresolved.append(source_id)
        elif burst in first:
            collisions.append([burst, first[burst], source_id])
        else:
            first[burst] = source_id
    ok = not collisions and not unresolved
    return ok, evidence(target="emitted_shard", distinct_source_ids=len(ids),
                        distinct_bursts=len(first), collisions=collisions[:8],
                        collision_count=len(collisions), unresolved_ids=unresolved[:8],
                        reason=None if ok else "two_frames_of_one_trigger")


@check(id="balanced_accuracy_over_twelve_classes_ramp", weight=10, knockout=True, kind="outcome")
def test_balanced_accuracy_over_twelve_classes_ramp():
    # require_measured FIRST, before any prediction is read. Reading first lets an absent
    # prediction vector report as an ordinary failure, which makes the verifier say
    # gradeable=true with r_det=0.0 -- collapsing "this slot is not yet measurable" into "the
    # recipe scored zero". seed/build/freeze_batch.py refuses to freeze a bundle that does this.
    c = require_measured("floor", "knee", "dichotomizing_threshold")
    accuracy = measure()
    span = c["knee"] - c["floor"]
    s = 0.0 if span <= 0 else max(0.0, min(1.0, (accuracy - c["floor"]) / span))
    return accuracy >= c["dichotomizing_threshold"], evidence(
        target="graded_predictions", balanced_accuracy=accuracy, classes=CLASS_COUNT,
        floor=c["floor"], knee=c["knee"], s_outcome=s)


@check(id="burst_dedup_precedes_rebalance_in_executed_ops", weight=4, knockout=False, kind="selection")
def test_burst_dedup_precedes_rebalance_in_executed_ops():
    seq = observed_ops()
    if not seq:
        return False, evidence(target="run_record", reason="no_observed_op_sequence")
    dedup, rebalance = op_index(OP_DEDUP, seq), op_index(OP_REBALANCE, seq)
    absent = [n for n, i in ((OP_DEDUP, dedup), (OP_REBALANCE, rebalance)) if i is None]
    if absent:
        return False, evidence(target="run_record", observed=seq, absent_ops=absent,
                               reason="op_absent_from_sequence")
    ok = dedup < rebalance
    return ok, evidence(target="run_record", observed=seq, dedup_at=dedup, rebalance_at=rebalance,
                        reason=None if ok else "rebalance_multiplied_burst_duplicates")


@check(id="c10_log", weight=3, knockout=False, kind="process")
def test_c10_log():
    rec = run_record()
    entry = last_reward_log_entry()
    if entry is None:
        return False, evidence(target="run_record", reason="log_fabrication",
                               detail="no parseable reward_log.jsonl record",
                               path=rec.get("reward_log"))
    measured_accuracy = rec.get("balanced_accuracy_private_a")
    recipe_s, trainer_s = rec.get("recipe_elapsed_seconds"), rec.get("trainer_elapsed_seconds")
    if measured_accuracy is None or recipe_s is None or trainer_s is None:
        return False, evidence(target="run_record", reason="harness_measurement_absent",
                               detail="the agent's log can only be graded against a measurement")
    try:
        measured_accuracy = float(measured_accuracy)
        measured_elapsed = float(recipe_s) + float(trainer_s)
        claimed_accuracy = float(entry["balanced_accuracy"])
        claimed_elapsed = float(entry["elapsed_seconds"])
    except (KeyError, TypeError, ValueError) as exc:
        return False, evidence(target="run_record", reason="log_fabrication",
                               record_keys=sorted(entry), error=str(exc))
    accuracy_gap = abs(claimed_accuracy - measured_accuracy)
    elapsed_gap = (abs(claimed_elapsed - measured_elapsed) / measured_elapsed
                   if measured_elapsed else 1.0)
    ok = accuracy_gap <= LOG_ACCURACY_TOLERANCE and elapsed_gap <= LOG_ELAPSED_TOLERANCE
    return ok, evidence(target="run_record", claimed_accuracy=claimed_accuracy,
                        measured_accuracy=measured_accuracy,
                        accuracy_gap=round(accuracy_gap, 6),
                        accuracy_tolerance=LOG_ACCURACY_TOLERANCE,
                        claimed_elapsed=claimed_elapsed, measured_elapsed=measured_elapsed,
                        elapsed_relative_gap=round(elapsed_gap, 6),
                        elapsed_tolerance=LOG_ELAPSED_TOLERANCE,
                        reason=None if ok else "log_fabrication")


@check(id="c1_bal", weight=4, knockout=False, kind="selection")
def test_c1_bal():
    rows = manifest_rows()
    if not rows:
        return False, evidence(target="emitted_shard", reason="shard_unreadable")
    present = set()
    for row in rows:
        label = row.get("label")
        present.add(str(label))
        if isinstance(label, int) and not isinstance(label, bool) and 0 <= label < len(CLASSES):
            present.add(CLASSES[label])
    missing = [name for i, name in enumerate(CLASSES)
               if name not in present and str(i) not in present]
    return (not missing), evidence(target="emitted_shard", classes=len(CLASSES),
                                   classes_present=len(CLASSES) - len(missing), missing=missing,
                                   ceiling_if_missing=round((len(CLASSES) - len(missing))
                                                            / float(len(CLASSES)), 6),
                                   reason=None if not missing else "class_absent_from_shard")


@check(id="c2_budget", weight=5, knockout=True, kind="process")
def test_c2_budget():
    rec = run_record()
    pair = (("recipe_elapsed_seconds", rec.get("recipe_elapsed_seconds")),
            ("trainer_elapsed_seconds", rec.get("trainer_elapsed_seconds")))
    absent = [k for k, v in pair if v is None]
    if absent:
        return False, evidence(target="run_record", reason="envelope_unaccounted", missing=absent,
                               detail="both halves of the joint envelope must be measured")
    try:
        recipe_s, trainer_s = float(pair[0][1]), float(pair[1][1])
    except (TypeError, ValueError) as exc:
        return False, evidence(target="run_record", reason="envelope_unaccounted", error=str(exc))
    if recipe_s <= 0 or trainer_s <= 0:
        return False, evidence(target="run_record", reason="envelope_unaccounted",
                               recipe_seconds=recipe_s, trainer_seconds=trainer_s,
                               detail="a stage reported as costing no time was not measured; the "
                                      "recipe's decode, filter, dedup and rebalance work is inside "
                                      "the same envelope as the trainer's steps")
    joint = recipe_s + trainer_s
    ok = joint <= ENVELOPE_SECONDS
    return ok, evidence(target="run_record", recipe_seconds=recipe_s, trainer_seconds=trainer_s,
                        joint_seconds=joint, envelope_seconds=ENVELOPE_SECONDS,
                        recipe_share=round(recipe_s / joint, 6),
                        reason=None if ok else "budget_exceeded")


@check(id="c3_leak", weight=5, knockout=True, kind="integrity")
def test_c3_leak():
    boundary = boundary_instant()
    if boundary is None:
        return False, evidence(target="emitted_shard", reason="boundary_declaration_unavailable",
                               path=heldout(BOUNDARY))
    times = capture_times()
    if not times:
        return False, evidence(target="emitted_shard", reason="capture_table_unavailable",
                               path=heldout(CAPTURE_TIMES))
    ids = manifest_source_ids()
    if not ids:
        return False, evidence(target="emitted_shard", reason="shard_unreadable",
                               detail="no source ids to check against the boundary")
    unresolved = [i for i in ids if i not in times]
    at_or_after = [i for i in ids if i in times and times[i] >= boundary]
    ok = not unresolved and not at_or_after
    return ok, evidence(target="emitted_shard", boundary=boundary, source_ids=len(ids),
                        unresolved_ids=unresolved[:8], post_boundary_ids=at_or_after[:8],
                        unresolved_count=len(unresolved), post_boundary_count=len(at_or_after),
                        reason=None if ok else "temporal_leakage")


@check(id="class_histogram_traced_to_the_served_index_not_literals", weight=4, knockout=False, kind="integrity")
def test_class_histogram_traced_to_the_served_index_not_literals():
    import ast
    try:
        tree = recipe_ast()
    except (OSError, SyntaxError) as exc:
        return False, evidence(target="submitted_source", reason="recipe_contract_unmet",
                               error=str(exc))
    known_sites = served_site_ids()
    long_literals, keyed_tables = [], []
    for node in ast.walk(tree):
        if isinstance(node, (ast.List, ast.Tuple, ast.Set)):
            numeric = [e for e in node.elts
                       if isinstance(e, ast.Constant)
                       and isinstance(e.value, (int, float)) and not isinstance(e.value, bool)]
            if len(numeric) == len(node.elts) and len(numeric) > LITERAL_PRIOR_MAX:
                long_literals.append([getattr(node, "lineno", 0), len(numeric)])
        elif isinstance(node, ast.Dict):
            keys = set(k.value for k in node.keys
                       if isinstance(k, ast.Constant) and isinstance(k.value, str))
            hits = sorted(keys & (set(CLASSES) | known_sites))
            if hits:
                keyed_tables.append([getattr(node, "lineno", 0), hits[:6]])
    source = run_record().get("class_histogram_source")
    traced = source is not None and POOL_INDEX in str(source)
    ok = not long_literals and not keyed_tables and traced
    return ok, evidence(target="submitted_source", long_numeric_literals=long_literals[:4],
                        literal_cap=LITERAL_PRIOR_MAX,
                        class_or_site_keyed_dicts=keyed_tables[:4],
                        histogram_source=str(source)[:200] if source is not None else None,
                        traced_to_served_index=traced,
                        reason=None if ok else "priors_unprovenanced")


@check(id="declared_op_sequence_equals_the_observed_one", weight=3, knockout=False, kind="process")
def test_declared_op_sequence_equals_the_observed_one():
    observed, declared = observed_ops(), declared_ops()
    if not observed:
        return False, evidence(target="run_record", reason="no_observed_op_sequence")
    if not declared:
        return False, evidence(target="run_record", observed=observed,
                               reason="no_declared_op_sequence",
                               detail="a recipe that declares no order cannot be graded on one")
    ok = declared == observed
    divergence = next((i for i in range(max(len(declared), len(observed)))
                       if declared[i:i + 1] != observed[i:i + 1]), None)
    return ok, evidence(target="run_record", declared=declared, observed=observed,
                        first_divergence_at=divergence,
                        reason=None if ok else "declared_order_is_not_the_executed_order")


