@check(id="emitted_row_count_within_cap_counting_repeats", weight=3, knockout=False, kind="selection")
def test_emitted_row_count_within_cap_counting_repeats():
    rows = manifest_rows()
    if not rows:
        return False, evidence(target="emitted_shard", reason="shard_unreadable")
    total = len(rows)
    distinct = len(manifest_source_ids())
    claimed = (shard_manifest() or {}).get("sample_count")
    misreported = False
    if claimed is not None:
        try:
            misreported = int(claimed) != total
        except (TypeError, ValueError):
            misreported = True
    over = total > SAMPLE_CAP_ROWS
    ok = not over and not misreported
    reason = "shard_cap_exceeded" if over else (
        "sample_count_counted_distinct_not_rows" if misreported else None)
    return ok, evidence(target="emitted_shard", sample_rows=total, distinct_source_ids=distinct,
                        upsampled_repeats=total - distinct, declared_sample_count=claimed,
                        cap=SAMPLE_CAP_ROWS, reason=reason)


@check(id="emitted_shard_manifest_admissible", weight=5, knockout=True, kind="deliverable")
def test_emitted_shard_manifest_admissible():
    path = manifest_path()
    if not path:
        return False, evidence(target="emitted_shard", reason="shard_unreadable",
                               detail="the run record names neither out_dir nor a manifest path")
    if not os.path.exists(path):
        return False, evidence(target="emitted_shard", reason="shard_unreadable", path=path,
                               detail="build() returned without leaving %s" % MANIFEST_NAME)
    if shard_manifest() is None:
        return False, evidence(target="emitted_shard", reason="shard_unreadable", path=path,
                               detail="the manifest does not parse as a JSON object")
    rows = manifest_rows()
    if not rows:
        return False, evidence(target="emitted_shard", reason="shard_unreadable", path=path,
                               detail="the samples list is absent or empty")
    missing = sorted(set(f for f in MANIFEST_FIELDS for r in rows if f not in r))
    return (not missing), evidence(target="emitted_shard", path=path, sample_rows=len(rows),
                                   required_fields=list(MANIFEST_FIELDS), missing_fields=missing,
                                   reason=None if not missing else "shard_unreadable")


@check(id="frozen_trainer_digests_unchanged_across_the_recipe", weight=4, knockout=False, kind="integrity")
def test_frozen_trainer_digests_unchanged_across_the_recipe():
    rec = run_record()
    before = rec.get("frozen_digests_before") or {}
    after = rec.get("frozen_digests_after") or {}
    if not isinstance(before, dict) or not isinstance(after, dict) or not before or not after:
        return False, evidence(target="run_record", reason="frozen_digests_unrecorded",
                               before=sorted(before) if isinstance(before, dict) else None,
                               after=sorted(after) if isinstance(after, dict) else None)
    moved = sorted(k for k in set(before) | set(after) if before.get(k) != after.get(k))
    touched = sorted(str(p) for p in (rec.get("guarded_paths_touched") or [])
                     if any(str(p).startswith(g) for g in GUARDED))
    imports = frozen_trainer_imports()
    ok = not moved and not touched and not imports
    return ok, evidence(target="run_record", digests_compared=sorted(set(before) | set(after)),
                        digests_moved=moved, guarded_paths_touched=touched[:8],
                        frozen_package_imports=imports[:6],
                        reason=None if ok else "trainer_modified")


@check(id="internal_validation_holds_out_latest_preboundary_window", weight=4, knockout=False, kind="process")
def test_internal_validation_holds_out_latest_preboundary_window():
    rec = run_record()
    policy = rec.get("split_policy")
    if policy is None:
        return False, evidence(target="run_record", reason="no_split_policy_declared")
    text = str(policy).lower()
    leaking = [w for w in ("shuffle", "shuffled", "random_split", "random split", "kfold",
                           "k-fold", "stratifiedkfold", "permut") if w in text]
    ordered = any(w in text for w in ("ordered", "chronological", "time_order", "time order",
                                      "expanding", "rolling", "latest", "holdout by date"))
    stamps = rec.get("split_timestamps") or {}
    train = sorted(str(t) for t in (stamps.get("train") or []))
    validation = sorted(str(t) for t in (stamps.get("validation") or []))
    if not train or not validation:
        return False, evidence(target="run_record", declared=str(policy)[:200],
                               reason="split_timestamps_unrecorded")
    straddles = validation[0] <= train[-1]
    ok = ordered and not leaking and not straddles
    return ok, evidence(target="run_record", declared=str(policy)[:200], leaking_tokens=leaking,
                        names_an_order=ordered, latest_train=train[-1],
                        earliest_validation=validation[0], straddles=straddles,
                        reason=None if ok else "validation_split_is_not_time_ordered")


@check(id="night_ir_statistics_computed_before_augmentation", weight=4, knockout=False, kind="process")
def test_night_ir_statistics_computed_before_augmentation():
    seq = observed_ops()
    if not seq:
        return False, evidence(target="run_record", reason="no_observed_op_sequence")
    stats_at = op_index(OP_STATISTICS, seq)
    if stats_at is None:
        return False, evidence(target="run_record", observed=seq, absent_ops=[OP_STATISTICS],
                               reason="op_absent_from_sequence")
    early = [op for op in AUGMENTATION_OPS
             if op_index(op, seq) is not None and op_index(op, seq) < stats_at]
    recorded = run_record().get("normalization_statistics")
    keyed = sorted(recorded) if isinstance(recorded, dict) else []
    pooled = [regime for regime in ILLUMINATION_REGIMES if regime not in keyed]
    ok = not early and not pooled
    return ok, evidence(target="run_record", observed=seq, statistics_at=stats_at,
                        augmentation_before_statistics=early, regimes_keyed=keyed,
                        regimes_missing=pooled,
                        reason=None if ok else "night_ir_statistics_folded_into_daylight")


