@check(id="replay_reproduces_shard_and_prediction_digests", weight=3, knockout=False, kind="process")
def test_replay_reproduces_shard_and_prediction_digests():
    rec = run_record()
    first = rec.get("first_run_digests") or {}
    replay = rec.get("replay_digests") or {}
    wanted = ("shard_manifest", "trainer_parameters", "private_a_predictions")
    if not isinstance(first, dict) or not isinstance(replay, dict):
        return False, evidence(target="run_record", reason="replay_unavailable")
    absent = [k for k in wanted if not first.get(k) or not replay.get(k)]
    if absent:
        return False, evidence(target="run_record", reason="replay_unavailable", missing=absent)
    diverged = [k for k in wanted if first[k] != replay[k]]
    return (not diverged), evidence(target="run_record", compared=list(wanted),
                                    diverged=diverged, trainer_steps=TRAINER_STEPS,
                                    reason=None if not diverged else "replay_diverged")


@check(id="selected_sites_span_the_served_camera_roster", weight=3, knockout=False, kind="selection")
def test_selected_sites_span_the_served_camera_roster():
    rows = manifest_rows()
    if not rows:
        return False, evidence(target="emitted_shard", reason="shard_unreadable")
    sites = site_of()
    if not sites:
        return False, evidence(target="emitted_shard", reason="pool_index_unavailable",
                               path=bundle(POOL_INDEX))
    counts, unresolved = {}, 0
    for row in rows:
        site = sites.get(str(row.get("source_id")))
        if site is None:
            unresolved += 1
        else:
            counts[site] = counts.get(site, 0) + 1
    placed = sum(counts.values())
    roster = len(set(sites.values()))
    coverage = (len(counts) / float(roster)) if roster else 0.0
    largest = (max(counts.values()) / float(placed)) if placed else 1.0
    ok = (unresolved == 0 and coverage >= SITE_COVERAGE_FLOOR
          and largest <= MAX_SINGLE_SITE_SHARE)
    return ok, evidence(target="emitted_shard", sites_selected=len(counts), roster_sites=roster,
                        coverage=round(coverage, 6), coverage_floor=SITE_COVERAGE_FLOOR,
                        largest_site_share=round(largest, 6),
                        largest_site_share_cap=MAX_SINGLE_SITE_SHARE, unresolved_rows=unresolved,
                        reason=None if ok else "selection_collapsed_onto_few_cameras")


@check(id="selection_keyed_to_index_fields_not_row_offsets", weight=3, knockout=False, kind="integrity")
def test_selection_keyed_to_index_fields_not_row_offsets():
    import ast
    try:
        source = recipe_source()
        tree = recipe_ast()
    except (OSError, SyntaxError) as exc:
        return False, evidence(target="submitted_source", reason="recipe_contract_unmet",
                               error=str(exc))
    named = sorted(f for f in POOL_FIELDS if f in source)
    poolish = ("pool", "index", "rows", "records", "catalog")
    offsets = []
    for node in ast.walk(tree):
        if not isinstance(node, ast.Subscript) or not isinstance(node.slice, ast.Slice):
            continue
        base = node.value
        name = base.id if isinstance(base, ast.Name) else getattr(base, "attr", "")
        if not any(token in str(name).lower() for token in poolish):
            continue
        bounds = [b for b in (node.slice.lower, node.slice.upper) if b is not None]
        if any(isinstance(b, ast.Constant) and isinstance(b.value, int) for b in bounds):
            offsets.append([getattr(node, "lineno", 0), str(name)])
    ok = len(named) >= 2 and not offsets
    return ok, evidence(target="submitted_source", fields_named=named,
                        fields_available=list(POOL_FIELDS), positional_slices=offsets[:6],
                        reason=None if ok else "keyed_to_row_offsets_not_fields")


@check(id="sibling_shard_gap_within_bound", weight=3, knockout=False, kind="generalisation")
def test_sibling_shard_gap_within_bound():
    rec = run_record()
    a, b = rec.get("balanced_accuracy_private_a"), rec.get("balanced_accuracy_private_b")
    if a is None or b is None:
        return False, evidence(target="graded_predictions", reason="sibling_measurement_absent",
                               private_a=a, private_b=b)
    try:
        a, b = float(a), float(b)
    except (TypeError, ValueError) as exc:
        return False, evidence(target="graded_predictions",
                               reason="sibling_measurement_absent", error=str(exc))
    gap = abs(a - b)
    ok = gap <= SIBLING_GAP_BOUND
    return ok, evidence(target="graded_predictions", private_a=a, private_b=b,
                        gap=round(gap, 6), bound=SIBLING_GAP_BOUND,
                        reason=None if ok else "sibling_gap_violation")


# ------------------------------------------------------------------------------------------
# Reading the delivered bytes. Five sources: the recipe source, the shard manifest build()
# wrote, the served pool index, the verifier-held tables, and the harness run record. Each is
# read the same way everywhere -- absent is REPORTED under its own name, never guessed at and
# never allowed to look like a pass.
# ------------------------------------------------------------------------------------------

def bundle(rel):
    """A path relative to the bundle root, from the checker tree."""
    return os.path.normpath(os.path.join(HERE, "..", rel))


def heldout(name):
    """A verifier-side table. Lives under tests/heldout/ and the graded run may not read it."""
    return os.path.join(HERE, "heldout", name)


def run_record():
    path = os.path.normpath(os.path.join(HERE, RUN_RECORD))
    if not os.path.exists(path):
        return {}
    try:
        with open(path) as handle:
            doc = json.load(handle)
    except Exception:
        return {}
    return doc if isinstance(doc, dict) else {}


def recipe_source():
    """The recipe as TEXT. It is never imported: importing it to inspect it would run it."""
    with open(SUBMISSION, encoding="utf-8", errors="replace") as handle:
        return handle.read()


def recipe_ast():
    """The parsed recipe. Raises SyntaxError, which every caller reports rather than swallows."""
    import ast
    return ast.parse(recipe_source(), filename=SUBMISSION)


def module_level_functions():
    """name -> node for every function defined at module level, in source order."""
    import ast
    out = {}
    try:
        tree = recipe_ast()
    except (OSError, SyntaxError):
        return out
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            out[node.name] = node
    return out


def build_signature():
    """(positional parameter names, node) for the module-level build, else (None, None)."""
    node = module_level_functions().get("build")
    if node is None:
        return None, None
    args = node.args
    return [p.arg for p in list(args.posonlyargs) + list(args.args)], node


def frozen_trainer_imports():
    """Lines where the recipe imports the frozen trainer package. The shard is the only channel."""
    import ast
    try:
        tree = recipe_ast()
    except (OSError, SyntaxError):
        return []
    hits = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            names = [a.name for a in node.names]
        elif isinstance(node, ast.ImportFrom):
            names = [node.module or ""]
        else:
            continue
        for name in names:
            if name == FROZEN_PACKAGE or name.startswith(FROZEN_PACKAGE + "."):
                hits.append([getattr(node, "lineno", 0), name])
    return hits


def manifest_path():
    """Where build() said it put the manifest, else MANIFEST_NAME under the out_dir it was given."""
    rec = run_record()
    declared = rec.get("emitted_shard_manifest")
    if declared:
        return str(declared)
    out_dir = rec.get("out_dir")
    return os.path.join(str(out_dir), MANIFEST_NAME) if out_dir else None


def shard_manifest():
    path = manifest_path()
    if not path or not os.path.exists(path):
        return None
    try:
        with open(path) as handle:
            doc = json.load(handle)
    except Exception:
        return None
    return doc if isinstance(doc, dict) else None


def manifest_rows():
    """One row per SAMPLE, so an upsampled rare-class image appears once per repeat."""
    doc = shard_manifest() or {}
    rows = doc.get("samples")
    return [r for r in rows if isinstance(r, dict)] if isinstance(rows, list) else []


def manifest_source_ids():
    return sorted({str(r.get("source_id")) for r in manifest_rows() if r.get("source_id") is not None})


def observed_ops():
    """The op names the HARNESS watched build() execute, in order. Never the recipe's own claim."""
    seq = run_record().get("observed_op_sequence")
    return [str(op) for op in seq] if isinstance(seq, list) else []


def declared_ops():
    """The op order the manifest claims. Graded against observed_ops, never trusted alone."""
    seq = (shard_manifest() or {}).get(DECLARED_OPS_KEY)
    return [str(op) for op in seq] if isinstance(seq, list) else []


def op_index(name, sequence):
    return sequence.index(name) if name in sequence else None


def pool_rows():
    """The SERVED pool index: a run-indexed rotated subsample, addressed by field not offset."""
    import csv
    path = bundle(POOL_INDEX)
    if not os.path.exists(path):
        return []
    try:
        with open(path, newline="") as handle:
            return [r for r in csv.DictReader(handle)]
    except Exception:
        return []


def pool_field(field):
    """image_id -> that field, over the served index."""
    return dict((str(r.get("image_id")), str(r.get(field)))
                for r in pool_rows() if r.get("image_id") is not None and r.get(field) is not None)


def burst_of():
    return pool_field("burst_id")


def site_of():
    return pool_field("site_id")


def served_site_ids():
    return set(site_of().values())


def capture_times():
    """source id -> capture timestamp, held VERIFIER-SIDE.

    C3-LEAK re-derives the boundary decision from this table rather than from the timestamp the
    recipe wrote into its own manifest. A recipe that mislabels its rows must not be able to
    relabel its way past the one red line the task has zero tolerance for.
    """
    import csv
    path = heldout(CAPTURE_TIMES)
    if not os.path.exists(path):
        return {}
    try:
        with open(path, newline="") as handle:
            return dict((str(r.get("image_id")), str(r.get("capture_timestamp")))
                        for r in csv.DictReader(handle))
    except Exception:
        return {}


def boundary_instant():
    """The declared boundary, as an ISO-8601 instant.

    Timestamps are compared as STRINGS. ISO-8601 in a fixed zone with fixed field widths orders
    lexicographically, which keeps the comparison free of a timezone library the verifier
    environment may not carry. Phase 1 must emit both tables in that form.
    """
    path = heldout(BOUNDARY)
    if not os.path.exists(path):
        return None
    try:
        with open(path) as handle:
            return json.load(handle).get("boundary")
    except Exception:
        return None


def last_reward_log_entry():
    """The final parseable record of the agent's own reward_log.jsonl, or None."""
    path = run_record().get("reward_log")
    if not path or not os.path.exists(str(path)):
        return None
    last = None
    try:
        with open(str(path)) as handle:
            for line in handle:
                line = line.strip()
                if not line:
                    continue
                try:
                    row = json.loads(line)
                except Exception:
                    continue
                if isinstance(row, dict):
                    last = row
    except Exception:
        return None
    return last


def graded_predictions():
    """The frozen trainer's private_A prediction vector, written verifier-side after step 6000."""
    import numpy as np
    return np.load(heldout(PREDICTIONS_A), allow_pickle=False).astype("int64").ravel()


def private_a_labels():
    import numpy as np
    return np.load(heldout(LABELS_A), allow_pickle=False).astype("int64").ravel()


def measure():
    """Macro-averaged balanced accuracy: mean per-class RECALL over the twelve classes.

    Recall per class, then a flat mean over classes -- not overall accuracy. The distinction is
    the whole point of the metric: the eleven-species-plus-empty vocabulary is heavily skewed, so
    a shard that raises overall accuracy by dropping the rare classes lowers this number.
    """
    predicted, truth = graded_predictions(), private_a_labels()
    if not len(predicted) or not len(truth):
        raise ConstantUnmeasured("the graded prediction vector or its private labels are absent")
    n = min(len(predicted), len(truth))
    predicted, truth = predicted[:n], truth[:n]
    recalls = []
    for label in range(CLASS_COUNT):
        support = truth == label
        if not support.any():
            raise ConstantUnmeasured("class %s has no support on private_A" % label)
        recalls.append(float((predicted[support] == label).mean()))
    return float(sum(recalls) / len(recalls))
